export interface JsonViewerProps extends Omit<React.ComponentProps<"div">, "children"> {
  data: unknown
  /** Containers shallower than this start open. Default 1: the top level is open. */
  defaultExpandDepth?: number
  /** Show the search field and toolbar. On by default. */
  toolbar?: boolean
  /** Strings longer than this are cut with an expand control. Default 120. */
  maxStringLength?: number
  /** Children shown per container before a "Show more" row. Default 100. */
  pageSize?: number
  /** Height of the tree. Number means px. Default 360. */
  maxHeight?: number | string
  /** Accessible name for the tree. */
  label?: string
  /** Initial search, for example to point at one field. */
  defaultQuery?: string
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type JsonPath = (string | number)[]

function entriesOf(value: unknown): [string | number, unknown][] {
  if (Array.isArray(value)) return value.map((v, i) => [i, v])
  if (value && typeof value === "object") return Object.entries(value as Record<string, unknown>)
  return []
}

type Kind = "object" | "array" | "string" | "number" | "boolean" | "null" | "undefined" | "other"

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function kindOf(value: unknown): Kind {
  if (value === null) return "null"
  if (Array.isArray(value)) return "array"
  const t = typeof value
  if (t === "object") return "object"
  if (t === "string" || t === "number" || t === "boolean" || t === "undefined") return t
  return "other"
}

/** JSONPath: `$.items[0].name`, with bracket notation for keys that are not identifiers. */
export function formatPath(path: JsonPath) {
  let out = "$"
  for (const seg of path) {
    if (typeof seg === "number") out += `[${seg}]`
    else if (/^[A-Za-z_$][\w$]*$/.test(seg)) out += `.${seg}`
    else out += `[${JSON.stringify(seg)}]`
  }
  return out
}

/** Ids of every container up to `depth`, for the initial open state. */
function containersTo(data: unknown, depth: number) {
  const ids = new Set<string>()
  const walk = (value: unknown, path: JsonPath, d: number) => {
    if (d >= depth) return
    for (const [k, v] of entriesOf(value)) {
      const child = [...path, k]
      const kind = kindOf(v)
      if (kind === "object" || kind === "array") {
        ids.add(formatPath(child))
        walk(v, child, d + 1)
      }
    }
  }
  walk(data, [], 0)
  return ids
}

/** Paths whose key or primitive value contains `query`, plus every ancestor id of a match. */
function search(data: unknown, query: string) {
  const q = query.toLowerCase()
  const matches: string[] = []
  const ancestors = new Set<string>()
  const walk = (value: unknown, path: JsonPath, chain: string[]) => {
    for (const [k, v] of entriesOf(value)) {
      const child = [...path, k]
      const id = formatPath(child)
      const kind = kindOf(v)
      const keyHit = typeof k === "string" && k.toLowerCase().includes(q)
      const valueHit = kind !== "object" && kind !== "array" && String(v).toLowerCase().includes(q)
      if (keyHit || valueHit) {
        matches.push(id)
        for (const a of chain) ancestors.add(a)
      }
      if (kind === "object" || kind === "array") walk(v, child, [...chain, id])
    }
  }
  walk(data, [], [])
  return { matches, ancestors }
}

interface Row {
  type: "node"
  id: string
  path: JsonPath
  key: string | number | undefined
  value: unknown
  kind: Kind
  depth: number
  size: number
  parentId: string | null
  posinset: number
  setsize: number
}

type Line =
  | Row
  | { type: "close"; id: string; depth: number; kind: "object" | "array" }
  | { type: "more"; id: string; parentId: string; depth: number; remaining: number }

function flatten(
  data: unknown,
  expanded: Set<string>,
  limits: Record<string, number>,
  pageSize: number,
): Line[] {
  const lines: Line[] = []
  const walk = (value: unknown, path: JsonPath, depth: number, parentId: string | null) => {
    const entries = entriesOf(value)
    const limit = parentId ? (limits[parentId] ?? pageSize) : (limits.$ ?? pageSize)
    entries.slice(0, limit).forEach(([k, v], i) => {
      const child = [...path, k]
      const id = formatPath(child)
      const kind = kindOf(v)
      const size = kind === "object" || kind === "array" ? entriesOf(v).length : 0
      lines.push({
        type: "node",
        id,
        path: child,
        key: k,
        value: v,
        kind,
        depth,
        size,
        parentId,
        posinset: i + 1,
        setsize: entries.length,
      })
      if ((kind === "object" || kind === "array") && size > 0 && expanded.has(id)) {
        walk(v, child, depth + 1, id)
        lines.push({ type: "close", id: `${id}:close`, depth, kind })
      }
    })
    if (entries.length > limit) {
      lines.push({
        type: "more",
        id: `${parentId ?? "$"}:more`,
        parentId: parentId ?? "$",
        depth,
        remaining: entries.length - limit,
      })
    }
  }
  const rootKind = kindOf(data)
  if (rootKind === "object" || rootKind === "array") walk(data, [], 0, null)
  else {
    lines.push({
      type: "node",
      id: "$",
      path: [],
      key: undefined,
      value: data,
      kind: rootKind,
      depth: 0,
      size: 0,
      parentId: null,
      posinset: 1,
      setsize: 1,
    })
  }
  return lines
}

function stringify(value: unknown) {
  if (typeof value === "string") return value
  if (value === undefined) return "undefined"
  try {
    return JSON.stringify(value, null, 2) ?? String(value)
  } catch {
    return String(value)
  }
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

