function Highlight({ text, query }: { text: string; query: string }) {
  if (!query) return text
  const lower = text.toLowerCase()
  const q = query.toLowerCase()
  const parts: React.ReactNode[] = []
  let i = 0
  let at = lower.indexOf(q)
  while (at >= 0) {
    if (at > i) parts.push(text.slice(i, at))
    parts.push(
      <mark
        key={at}
        className="bg-(color:--chatcn-fill-active) text-(color:--chatcn-fg) rounded-[2px] shadow-[0_0_0_1px_var(--chatcn-border-strong)]"
      >
        {text.slice(at, at + q.length)}
      </mark>,
    )
    i = at + q.length
    at = lower.indexOf(q, i)
  }
  if (i < text.length) parts.push(text.slice(i))
  return <>{parts}</>
}

const plural = (n: number, one: string, many: string) =>
  `${n.toLocaleString()} ${n === 1 ? one : many}`

/* -------------------------------------------------------------------------------------------------
 * Value
 * -----------------------------------------------------------------------------------------------*/

function Value({
  row,
  open,
  query,
  fullString,
  maxStringLength,
  onExpandString,
}: {
  row: Row
  open: boolean
  query: string
  fullString: boolean
  maxStringLength: number
  onExpandString: () => void
}) {
  const { kind, value, size } = row
  if (kind === "object" || kind === "array") {
    const [l, r] = kind === "array" ? ["[", "]"] : ["{", "}"]
    if (size === 0) return <span className="text-(color:--chatcn-fg-subtle)">{`${l}${r}`}</span>
    if (open) return <span className="text-(color:--chatcn-fg-subtle)">{l}</span>
    return (
      <span className="text-(color:--chatcn-fg-subtle)">
        {l}
        <span className="text-[0.75rem]/[1rem] mx-1 font-sans">
          {kind === "array" ? plural(size, "item", "items") : plural(size, "key", "keys")}
        </span>
        {r}
      </span>
    )
  }
  if (kind === "string") {
    const text = value as string
    const cut = !fullString && text.length > maxStringLength
    const shown = cut ? text.slice(0, maxStringLength) : text
    return (
      <span className={cn("text-(color:--chatcn-green)", fullString && "break-all whitespace-pre-wrap")}>
        <Highlight text={JSON.stringify(shown).slice(0, cut ? -1 : undefined)} query={query} />
        {cut ? (
          <>
            <span className="text-(color:--chatcn-fg-subtle)">…"</span>
            <button
              type="button"
              tabIndex={-1}
              onClick={(event) => {
                event.stopPropagation()
                onExpandString()
              }}
              className={cn(
                "text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) ms-1.5 px-1 font-sans",
                "hover:bg-(color:--chatcn-fill-hover) ease-(--chatcn-ease-standard) transition-colors duration-150",
              )}
            >
              {`+${(text.length - maxStringLength).toLocaleString()} chars`}
            </button>
          </>
        ) : null}
      </span>
    )
  }
  // Value types in subtle hues, the way browser devtools color them: strings green, numbers blue,
  // booleans purple, null gray. The quotes and literals still say the type without color.
  if (kind === "number" || kind === "boolean") {
    return (
      <span className={kind === "number" ? "text-(color:--chatcn-blue)" : "text-(color:--chatcn-purple)"}>
        <Highlight text={String(value)} query={query} />
      </span>
    )
  }
  return (
    <span className="text-(color:--chatcn-fg-subtle)">
      <Highlight text={kind === "null" ? "null" : String(value)} query={query} />
    </span>
  )
}

