export function JsonViewer({
  data,
  defaultExpandDepth = 1,
  toolbar = true,
  maxStringLength = 120,
  pageSize = 100,
  maxHeight = 360,
  label = "JSON",
  defaultQuery = "",
  className,
  ...props
}: JsonViewerProps) {
  const [expanded, setExpanded] = React.useState(() => {
    const open = containersTo(data, defaultExpandDepth)
    if (defaultQuery) for (const id of search(data, defaultQuery).ancestors) open.add(id)
    return open
  })
  const [limits, setLimits] = React.useState<Record<string, number>>({})
  const [fullStrings, setFullStrings] = React.useState<Set<string>>(() => new Set())
  const [query, setQuery] = React.useState(defaultQuery)
  const [activeMatch, setActiveMatch] = React.useState(0)
  const [focusedId, setFocusedId] = React.useState<string | null>(null)
  const [announcement, setAnnouncement] = React.useState("")
  const rowRefs = React.useRef(new Map<string, HTMLDivElement>())
  const treeRef = React.useRef<HTMLDivElement>(null)
  const focusOnRender = React.useRef(false)
  const treeId = React.useId()

  React.useEffect(() => {
    if (!announcement) return
    const id = window.setTimeout(() => setAnnouncement(""), 1500)
    return () => window.clearTimeout(id)
  }, [announcement])

  const lines = React.useMemo(
    () => flatten(data, expanded, limits, pageSize),
    [data, expanded, limits, pageSize],
  )
  const rows = React.useMemo(() => lines.filter((l): l is Row => l.type === "node"), [lines])
  const found = React.useMemo(() => (query ? search(data, query) : null), [data, query])
  const matchSet = React.useMemo(() => new Set(found?.matches), [found])
  const activeId = found?.matches[activeMatch]
  const current = rows.find((r) => r.id === focusedId) ?? rows[0]

  // Move DOM focus only after keyboard navigation, never on pointer or search updates.
  React.useEffect(() => {
    if (!focusOnRender.current || !current) return
    focusOnRender.current = false
    rowRefs.current.get(current.id)?.focus({ preventScroll: true })
  }, [current])

  React.useEffect(() => {
    if (!activeId) return
    // Scroll the tree only, never the page around it.
    const row = rowRefs.current.get(activeId)
    const tree = treeRef.current
    if (!row || !tree) return
    const box = tree.getBoundingClientRect()
    const r = row.getBoundingClientRect()
    if (r.top < box.top) tree.scrollTop += r.top - box.top
    else if (r.bottom > box.bottom) tree.scrollTop += r.bottom - box.bottom
  }, [activeId])

  const toggle = (id: string, open?: boolean) => {
    setExpanded((prev) => {
      const next = new Set(prev)
      const want = open ?? !next.has(id)
      if (want) next.add(id)
      else next.delete(id)
      return next
    })
  }

  const runSearch = (value: string) => {
    setQuery(value)
    setActiveMatch(0)
    if (!value) return
    const { ancestors } = search(data, value)
    // Open the path to every match. The user can still close them afterwards.
    if (ancestors.size) setExpanded((prev) => new Set([...prev, ...ancestors]))
  }

  const copy = (text: string, message: string) => {
    navigator.clipboard
      ?.writeText(text)
      .then(() => setAnnouncement(message))
      .catch(() => setAnnouncement("Copy failed. Allow clipboard access and try again."))
  }

  const focusRow = (row: Row | undefined) => {
    if (!row) return
    focusOnRender.current = true
    setFocusedId(row.id)
  }

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (!current || event.target !== rowRefs.current.get(current.id)) return
    const index = rows.indexOf(current)
    const isContainer = (current.kind === "object" || current.kind === "array") && current.size > 0
    const open = expanded.has(current.id)
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
    const inward = rtl ? "ArrowLeft" : "ArrowRight"
    const outward = rtl ? "ArrowRight" : "ArrowLeft"
