    switch (event.key) {
      case "ArrowDown":
        focusRow(rows[index + 1])
        break
      case "ArrowUp":
        focusRow(rows[index - 1])
        break
      case "Home":
        focusRow(rows[0])
        break
      case "End":
        focusRow(rows.at(-1))
        break
      case inward:
        if (isContainer && !open) toggle(current.id, true)
        else if (isContainer) focusRow(rows[index + 1])
        break
      case outward:
        if (isContainer && open) toggle(current.id, false)
        else focusRow(rows.find((r) => r.id === current.parentId))
        break
      case "Enter":
