        copy(formatPath(current.path), `Copied path ${formatPath(current.path)}`)
        break
      default:
        handled = false
    }
    if (handled) event.preventDefault()
  }

  const allOpen = rows.every(
    (r) => !((r.kind === "object" || r.kind === "array") && r.size > 0) || expanded.has(r.id),
  )
  const empty = data === undefined

  return (
    <div
      data-slot="json-viewer"
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-inset) shadow-(--chatcn-shadow-border) text-(color:--chatcn-fg) flex flex-col overflow-hidden",
        "forced-colors:outline-1 forced-colors:outline-solid",
