            }}
            className={cn(
              "text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) placeholder:text-(color:--chatcn-fg-subtle) h-8 min-w-0 flex-1 bg-transparent px-1.5",
              "focus:outline-none [&::-webkit-search-cancel-button]:hidden",
            )}
          />
          {query ? (
            <>
              <span
                aria-live="polite"
                className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 px-1 tabular-nums"
              >
                {found?.matches.length
                  ? `${activeMatch + 1} of ${found.matches.length}`
                  : "No matches"}
              </span>
              <Button size="icon-xs" aria-label="Clear search" onClick={() => runSearch("")}>
                <XIcon />
              </Button>
            </>
          ) : null}
          <span aria-hidden="true" className="bg-(color:--chatcn-border) mx-1 h-4 w-px shrink-0" />
          <Tooltip content={allOpen ? "Collapse all" : "Expand all"}>
            <Button
              size="icon-xs"
              aria-label={allOpen ? "Collapse all" : "Expand all"}
              onClick={() =>
                setExpanded(allOpen ? new Set() : containersTo(data, Number.POSITIVE_INFINITY))
              }
