                      "chatcn-focus text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) hover:text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) h-6 px-1 font-sans",
                      "hover:bg-(color:--chatcn-fill-hover) ease-(--chatcn-ease-standard) transition-colors duration-150",
