    if (reducedMotion() || held || touched) return
    const full = QUERIES[step.query]!
    const done = step.typed >= full.length
    const id = window.setTimeout(
      () =>
        setStep((s) =>
          done
            ? { query: (s.query + 1) % QUERIES.length, typed: 0 }
            : { query: s.query, typed: s.typed + 1 },
        ),
      done ? REST_MS : TYPE_MS,
    )
    return () => window.clearTimeout(id)
  }, [step, held, touched])

  // Back on tour after a visitor's own search, the next search starts fresh.
  React.useEffect(() => {
    if (held || !touched) return
    setTouched(false)
    setStep((s) => ({ query: (s.query + 1) % QUERIES.length, typed: 0 }))
  }, [held, touched])

  const query = QUERIES[step.query]!.slice(0, step.typed)

  return (
    <FitFrame minWidth="38rem">
      <div className="flex w-full flex-col items-center justify-center gap-4 p-6">
        <div
          className="h-[21.5rem] w-full max-w-xl"
          onInput={() => {
            setTouched(true)
            hold()
          }}
          onPointerDown={() => {
            setTouched(true)
            hold()
          }}
        >
          <JsonViewer
            key={touched ? "mine" : `${step.query}:${query}`}
            data={RESULT}
            defaultExpandDepth={query ? 0 : 1}
            defaultQuery={query}
            maxHeight={286}
            label="search_logs result"
          />
        </div>
        <MoreOn slug="json-viewer">Search, fold, copy paths and values from any JSON. On</MoreOn>
      </div>
    </FitFrame>
  )
}
